set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select pg_temp.expect_error($q$select public.register_notification_device('91000000-0000-0000-0000-000000000001',jsonb_build_object('type','fcm','token',repeat('A',40),'installationProof',repeat('A',43)),'{}','UTC','en','{}')$q$,'42501');
reset role;
update public.notification_settings set native_ready=true;
set local role authenticated;
select public.register_notification_device('91000000-0000-0000-0000-000000000001',jsonb_build_object('type','fcm','token',repeat('A',40),'installationProof',repeat('A',43)),'{"weightReminder":true}','UTC','en','{}');
