insert into public.notification_jobs(device_id,owner_id,subscription_revision,event_key,kind,href,local_date,due_at,expires_at) select id,owner_id,subscription_revision,'native-old-owner','weight_reminder','/#/body-progress',current_date,now(),now()+interval '1 hour' from public.notification_devices where transport='fcm';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
