select pg_temp.expect_error($q$select public.register_notification_device('91000000-0000-0000-0000-000000000002',jsonb_build_object('type','fcm','token',repeat('A',40),'installationProof','AQ'||repeat('A',41)),'{}','UTC','en','{}')$q$,'42501');
select public.register_notification_device('91000000-0000-0000-0000-000000000002',jsonb_build_object('type','fcm','token',repeat('A',40),'installationProof',repeat('A',43)),'{"weightReminder":true}','UTC','en','{}');
select public.register_notification_device('92000000-0000-0000-0000-000000000002',jsonb_build_object('type','fcm','token',(select string_agg(md5(i::text),'') from generate_series(1,128) i),'installationProof',repeat('A',43)),'{}','UTC','en','{}');
