select pg_temp.assert_true((select char_length(endpoint)=4100 from public.notification_devices where device_key='92000000-0000-0000-0000-000000000002'),'maximum-length native token fits durable endpoint uniqueness');
select pg_temp.assert_true((select count(*)=0 from public.notification_jobs where event_key='native-old-owner' and status in ('pending','claimed')),'native handoff cancels old account delivery');
insert into public.notification_jobs(device_id,owner_id,subscription_revision,event_key,kind,href,local_date,due_at,expires_at) select id,owner_id,subscription_revision,'native-claim','weight_reminder','/#/body-progress',current_date,now(),now()+interval '1 hour' from public.notification_devices where device_key='91000000-0000-0000-0000-000000000002';
select pg_temp.assert_true(public.claim_notification_jobs(25,false)='[]','worker without Firebase skips native transport');
update public.notification_settings set native_ready=false;
select pg_temp.assert_true(public.claim_notification_jobs(25,true)='[]','worker cannot override disabled native server capability');
update public.notification_settings set native_ready=true;
truncate claim; insert into claim select public.claim_notification_jobs(25,true)->0;
select pg_temp.assert_true((select payload->'subscription'->>'type'='fcm' and payload->'subscription'->>'token'=repeat('A',40) from claim),'native worker receives the token descriptor without fetching it as a URL');
select public.confirm_notification_job((payload->>'id')::uuid,(payload->>'claimToken')::uuid,'retry',401) from claim;
select pg_temp.assert_true((select status='pending' and attempts=1 and due_at=now()+interval '5 seconds' from public.notification_jobs where event_key='native-claim'),'FCM OAuth expiration gets one bounded refresh retry');
update public.notification_jobs set due_at=now() where event_key='native-claim';
truncate claim; insert into claim select public.claim_notification_jobs(25,true)->0;
select public.confirm_notification_job((payload->>'id')::uuid,(payload->>'claimToken')::uuid,'invalid',400) from claim;
select pg_temp.assert_true((select not enabled from public.notification_devices where device_key='91000000-0000-0000-0000-000000000002'),'FCM UNREGISTERED400 disables current native token');
select pg_temp.assert_true((select enabled from public.notification_devices where device_key='92000000-0000-0000-0000-000000000002'),'native invalidation preserves another registered device');
rollback;
